package tests

// Copyright AGNTCY Contributors (https://github.com/agntcy)// SPDX-License-Identifier: Apache-2.0package testsimport (	"os/exec"	"time"	ginkgo "github.com/onsi/ginkgo/v2"	"github.com/onsi/gomega")var _ = ginkgo.Describe("SLIM Security & Adversarial Tests", func() {	ginkgo.Context("Adversarial: Unauthorized Access", func() {				ginkgo.It("rejects connection attempts without valid mTLS credentials", func() {			cmd := exec.Command("go", "run", "../tools/security-probe/main.go", "-mode=bad-tls", "-target=localhost:46357")			output, err := cmd.CombinedOutput()			gomega.Expect(err).NotTo(gomega.HaveOccurred())			ginkgo.GinkgoWriter.Println(string(output))		})	})		ginkgo.Context("Adversarial: Man-in-the-Middle (MitM)", func() {		ginkgo.It("MITM tool starts and listens", func() {			cmd := exec.Command("go", "run", "../tools/security-probe/main.go", "-mode=mitm-tamper", "-target=localhost:46357")			err := cmd.Start()			gomega.Expect(err).NotTo(gomega.HaveOccurred())			time.Sleep(1 * time.Second)			if cmd.Process != nil {				cmd.Process.Kill()			}		})	})})
